// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 a, uint256 b) public {
        vm.assume(actor != address(0));
        a = bound(a, 0, 1 ether);
        b = bound(b, 0, 1 ether);

        vm.deal(actor, a + b);

        vm.prank(actor);
        c.addToBalance{value: a}();

        uint256 mid = c.getBalance(actor);

        vm.prank(actor);
        c.addToBalance{value: b}();

        assertTrue(c.getBalance(actor) == mid + b);
    }
}
